    "id": "coord-mcq-155",
    "questionNumber": 155,
    "question": "Q155. (NEET Medium) How many moles of $\\text{AgCl}$ precipitate will be formed when excess silver nitrate ($\\text{AgNO}_3$) solution is added to one mole of $\\text{CoCl}_3 \\cdot 5\\text{NH}_3$?",
    "options": {
      "A": "$3\\text{ moles}$",
      "B": "$1\\text{ mole}$",
      "C": "$2\\text{ moles}$",
      "D": "$0\\text{ moles}$"
    },
    "optionsList": [
      "$3\\text{ moles}$",
      "$1\\text{ mole}$",
      "$2\\text{ moles}$",
      "$0\\text{ moles}$"
    ],
    "correctAnswer": "C",
    "correctIndex": 2,
    "explanation": "1. CONCEPT & PRINCIPLE:\nWerner's coordination theory: primary (ionizable) vs secondary (non-ionizable) valency.\n\n2. GIVEN INFORMATION / DATA:\nCompound $\\text{CoCl}_3 \\cdot 5\\text{NH}_3$; Cobalt has coordination number 6.\n\n3. FORMULA / EQUATION:\nFormulation: $[Co(NH_3)_5Cl]Cl_2 \\rightarrow [Co(NH_3)_5Cl]^{2+} + 2Cl^-$\n\n4. STEP-BY-STEP REASONING & CALCULATION:\n1. Cobalt(III) maintains a fixed coordination number of 6 (secondary valency).\n2. With five $NH_3$ molecules available, one chloride ion must enter the coordination sphere to complete the octet/coordination number of 6: $[Co(NH_3)_5Cl]^{2+}$.\n3. The remaining two chloride ions satisfy primary valency outside the coordination bracket: $[Co(NH_3)_5Cl]Cl_2$.\n4. Only the ionizable chloride ions outside the coordination entity dissociate in aqueous solution: $[Co(NH_3)_5Cl]Cl_2 \\rightarrow [Co(NH_3)_5Cl]^{2+} + 2Cl^-$.\n5. Therefore, addition of excess $AgNO_3$ precipitates exactly 2 moles of $AgCl$ per mole of complex: $2Cl^- + 2Ag^+ \\rightarrow 2AgCl(s)$.\n\n5. FINAL CONCLUSION:\n$2\\text{ moles}$\n\n6. OPTION ANALYSIS & COMMON TRAPS:\n$3\\text{ moles}$ precipitates only for $[Co(NH_3)_6]Cl_3$; $1\\text{ mole}$ precipitates for $[Co(NH_3)_4Cl_2]Cl$.",
    "solutionStructured": {
      "concept": "Werner's coordination theory: primary (ionizable) vs secondary (non-ionizable) valency.",
      "given": "Compound $\\text{CoCl}_3 \\cdot 5\\text{NH}_3$; Cobalt has coordination number 6.",
      "formula": "Formulation: $[Co(NH_3)_5Cl]Cl_2 \\rightarrow [Co(NH_3)_5Cl]^{2+} + 2Cl^-$",
      "stepByStep": "1. Cobalt(III) maintains a fixed coordination number of 6 (secondary valency).\n2. With five $NH_3$ molecules available, one chloride ion must enter the coordination sphere to complete the octet/coordination number of 6: $[Co(NH_3)_5Cl]^{2+}$.\n3. The remaining two chloride ions satisfy primary valency outside the coordination bracket: $[Co(NH_3)_5Cl]Cl_2$.\n4. Only the ionizable chloride ions outside the coordination entity dissociate in aqueous solution: $[Co(NH_3)_5Cl]Cl_2 \\rightarrow [Co(NH_3)_5Cl]^{2+} + 2Cl^-$.\n5. Therefore, addition of excess $AgNO_3$ precipitates exactly 2 moles of $AgCl$ per mole of complex: $2Cl^- + 2Ag^+ \\rightarrow 2AgCl(s)$.",
      "finalAnswer": "$2\\text{ moles}$",
      "whyOtherOptionsWrong": "$3\\text{ moles}$ precipitates only for $[Co(NH_3)_6]Cl_3$; $1\\text{ mole}$ precipitates for $[Co(NH_3)_4Cl_2]Cl$."
    },
