      "concept": "Polydentate chelating agents and their clinical and analytical applications.",
      "given": "Ligand with 6 donor atoms forming extremely stable octahedral chelate rings.",
      "formula": "$[EDTA]^{4-}$ contains two nitrogen donor atoms and four oxygen carboxylate donor atoms.",
      "stepByStep": "1. Ethylenediaminetetraacetate ($EDTA^{4-}$) is a hexadentate ligand possessing two tertiary amino nitrogens and four carboxylate oxygens.\n2. When coordinating with polyvalent metal ions like $Ca^{2+}, Mg^{2+}$, or toxic heavy metals like $Pb^{2+}$, it wraps around the metal cation forming a stable cage-like complex with five five-membered chelate rings.\n3. The thermodynamic stability of the $[Pb(EDTA)]^{2-}$ chelate is exceptionally high, allowing safe excretion of lead through urine without disrupting normal physiological balance.\n4. It is also used in complexometric titration to estimate total hardness ($Ca^{2+} + Mg^{2+}$) of water.",
